node --input-type=module --eval 'import assert from "node:assert/strict"; import test from "node:test"; import vm from "node:vm"; import {readFileSync} from "node:fs";
test("CR-E081 completion observer refuses bounded-usage-read-postgres.test.ts skipped required bodies",()=>{
const source=readFileSync("tests/bounded-usage-read-postgres.test.ts","utf8"); const begin=source.lastIndexOf('"'"'\ntest("'"'"'); assert.ok(begin>=0,"real closing guard is loaded");
let guard; vm.runInNewContext(source.slice(begin), {test:(_name,fn)=>{guard=fn;},assert,PG:true,completed:0});
assert.equal(typeof guard,"function","the actual shard registered its completion guard");
assert.throws(guard,{code:"ERR_ASSERTION"},"independent incomplete-run observation must be refused");
});'

